#!/usr/bin/env bash
# EVrota backend 0.5.1 — ev sunucusunda (k8sskylight) çalıştır: sh evrota_0.5.1_update.sh
set -e
cd /opt/GIT/evrota-backend
git am --abort 2>/dev/null || true
git pull -q || true
if git log --oneline | grep -q "(0.5.1)"; then
  echo "0.5.1 zaten uygulanmış, derlemeye geçiliyor"
else
  echo '' | base64 -d | gunzip | git am
fi
git push
podman build -t docker.io/hafifbilgiler/evrota-backend:0.5.1 .
podman push docker.io/hafifbilgiler/evrota-backend:0.5.1
echo "Tamam: 0.5.1 gönderildi. Asıl sunucuda: git pull + kubectl apply"
